<template><div class="app-page"><header class="topnav"><strong>◉ SmartCity · {{t.forecast}}</strong><div class="nav-actions"><select :value="lang" @change="change($event.target.value)"><option value="sq">Shqip</option><option value="en">English</option></select><router-link to="/">{{t.back}}</router-link><button @click="auth.logout();router.push('/')">{{t.logout}}</button></div></header><main class="dashboard-shell"><div class="intro"><div><div class="eyebrow">STAFF ONLY</div><h1>{{t.forecast}}</h1><p>Trained model • PostgreSQL history • MQTT-triggered live cache</p></div></div><section class="surface"><div class="filters"><label>{{t.city}}<select v-model="city"><option value="">{{t.all}}</option><option v-for="c in cities" :key="c">{{c}}</option></select></label><label>{{t.horizon}}<select v-model.number="horizon"><option :value="3">3</option><option :value="6">6</option><option :value="12">12</option><option :value="24">24</option><option :value="48">48</option><option :value="72">72</option></select></label><button class="action" :disabled="busy" @click="run">{{busy?'…':t.run}}</button></div></section><p v-if="error" class="error-banner">{{error}}</p><section v-if="result" class="surface"><div class="section-title"><h2>{{t.status}}: {{result.status}}</h2><small>{{result.generated_at}}</small></div><p v-if="result.status!=='ml'" class="error-banner">{{t.modelWarn}} {{result.reason}}</p><p>Model: {{result.model_version||'—'}} · {{result.forecasts?.length||0}} predictions</p><div class="tablewrap"><table><thead><tr><th>{{t.city}}</th><th>Node</th><th>{{t.parameter}}</th><th>Time</th><th>Value</th><th>Method</th></tr></thead><tbody><tr v-for="(f,i) in result.forecasts?.slice(0,250)" :key="i"><td>{{f.city}}</td><td>{{f.node}}</td><td>{{f.param}}</td><td>{{f.timestamp}}</td><td>{{Number(f.value).toFixed(2)}}</td><td>{{f.method}}</td></tr></tbody></table></div></section></main></div></template>
<script setup>
import {ref} from 'vue';import {useRouter} from 'vue-router';import {useAuthStore} from '../../stores/auth';import {useLang,cities} from './i18n';import {runForecast} from '../../api/dashboard'
const {lang,t,change}=useLang(),auth=useAuthStore(),router=useRouter();const city=ref(''),horizon=ref(24),busy=ref(false),error=ref(''),result=ref(null)
async function run(){busy.value=true;error.value='';try{result.value=await runForecast(city.value,horizon.value)}catch(e){error.value=e.response?.data?.detail||e.message}finally{busy.value=false}}
</script>
